def apply_session() -> None:
    data = json.loads(SESSION.read_text(encoding="utf-8"))
    hits = 0
    for entry in data:
        tr = TRANSLATIONS.get(entry.get("id"))
        if tr:
            entry["thought_zh"] = tr["zh"]
            entry["thought_ja"] = tr["ja"]
            hits += 1
    SESSION.write_text(
        json.dumps(data, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    print(f"session.json: applied translations to {hits} / {len(data)} entries")


def apply_agents() -> None:
    data = json.loads(AGENTS.read_text(encoding="utf-8"))
    journey_hits = 0
    for agent in data.get("agents", []):
        meta = AGENT_META.get(agent.get("id"))
        if not meta:
            continue
        journey_meta = meta.get("journeys", {}) or {}
        for journey in agent.get("journeys", []):
            jmeta = journey_meta.get(journey.get("id"))
            if not jmeta:
                continue
            wrote = False
            for key in ("summary_zh", "summary_ja"):
                if jmeta.get(key):
                    journey[key] = jmeta[key]
                    wrote = True
            if wrote:
                journey_hits += 1
    AGENTS.write_text(
        json.dumps(data, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    print(f"agents.json: applied summary translations to {journey_hits} journeys")


if __name__ == "__main__":
    apply_session()
    apply_agents()
